import type { Actor, SessionPrincipal } from "@/types/member";

/** How long a freshly issued session cookie stays valid. */
const SESSION_TTL_DAYS = 30;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login.
 */
export async function createSessionToken(
  userId: UserId,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + SESSION_TTL_DAYS * MS_PER_DAY),
  );

  await sessionRepo.createSession(userId, hashToken(token), expiresAt);

  return { token, expiresAt };
}

export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  return sessionRepo.findSessionByTokenHash(hashToken(token));
}

/**
 * The bridge between "who is logged in" and "what may they do here": given a
 * principal and the org slug in the URL, produce the `Actor` every service
 * method takes, or `null` when the user is not a member of that org.
 *
 * The `assertOrgScope` call at the end looks redundant — the actor was just
 * built from that org — but it is the invariant this whole layer exists to
 * uphold, and it catches a mis-wired membership lookup immediately.
 */
export async function resolveActorForOrg(
  principal: SessionPrincipal,
  orgSlug: string,
): Promise<Actor | null> {
  const org = await orgRepo.findOrgBySlug(orgSlug);
  if (!org) return null;

  const member = await memberRepo.findMember(org.id, principal.userId);
  if (!member || member.status !== "active") return null;

  const actor: Actor = {
    userId: principal.userId,
    orgId: org.id,
    role: member.role,
  };

  assertOrgScope(actor, org.id);

  await memberRepo.touchLastSeen(
    org.id,
    principal.userId,
    toIsoTimestamp(new Date()),
  );

  return actor;
}

/**
 * Switches the org a session defaults to. Membership is re-checked here so a
 * removed member cannot pin their cookie to an org they left.
 *
 * `SessionPrincipal` carries no session id, so the write to `sessions.
 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
 * Action, which still holds the cookie. This method owns the authorization
 * half of the switch.
 */
export async function switchActiveOrg(
  principal: SessionPrincipal,
  input: SwitchOrgInput,
): Promise<void> {
  const member = await memberRepo.findMember(input.orgId, principal.userId);
  if (!member || member.status !== "active") {
    throw new Error("You are not a member of that organization");
  }

  const orgs = await orgRepo.listOrgsForUser(principal.userId);
  const target = orgs.find((org) => org.id === input.orgId);
  if (!target) throw new Error("You are not a member of that organization");

  assertOrgScope(
    { userId: principal.userId, orgId: input.orgId, role: member.role },
    target.id,
  );
}

/**
 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
 * exposes no session id, so the sweep is what actually clears the row, and the
 * cookie is dropped by the caller either way.
 */
export async function destroySession(token: string): Promise<void> {
  const principal = await resolveSession(token);
  if (!principal) return;

  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
}
/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { envelope, orgResource, requireFound } from "./_support";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
/**
 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
 *
 * Must call (do not reimplement): isEnabled, renderEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { renderEmail } from "./email-service";
import { buildFlagContext } from "./feature-flag-service";
import type { RenderedEmail } from "@/server/services/email-service";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { User } from "@/types/member";
import type { DigestBundle, DigestEntry } from "@/types/notification";

/** A digest with fewer entries than this is not worth an email. */
const MIN_ENTRIES = 1;

/**
 * Collects one recipient's unread notifications inside the window. Returns
 * `null` — rather than an empty bundle — when the org's plan does not include
 * the digest, or when there is nothing to say: the caller treats `null` as
 * "send nothing", so a quiet day produces no mail at all.
 */
export async function buildDigest(
  orgId: OrgId,
  recipientId: UserId,
  windowStart: IsoTimestamp,
  windowEnd: IsoTimestamp,
): Promise<DigestBundle | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;

  const unread = await notificationRepo.listUnreadSince(
    orgId,
    recipientId,
    windowStart,
  );

  const entries: DigestEntry[] = unread
    .filter((notification) => notification.createdAt <= windowEnd)
    .map((notification) => ({
      notificationId: notification.id,
      kind: notification.kind,
      title: notification.title,
      href: notification.href,
      occurredAt: notification.createdAt,
    }))
    .slice(0, DIGEST_MAX_ENTRIES);

  if (entries.length < MIN_ENTRIES) return null;

  return { orgId, recipientId, entries, windowStart, windowEnd };
}

/**
 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`. Opting into the digest is what suppresses the immediate
 * emails, so the two lists are two views of the same preference.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  return preferenceRepo.listDigestSubscribers(orgId);
}

/** Renders one bundle through the shared email pipeline. */
export async function renderDigest(
  bundle: DigestBundle,
  recipient: User,
): Promise<RenderedEmail> {
  return renderEmail("digest", {
    orgId: bundle.orgId,
    recipientName: recipient.name,
    entryCount: bundle.entries.length,
    windowStart: bundle.windowStart,
    windowEnd: bundle.windowEnd,
    headline: bundle.entries[0]?.title ?? "",
  });
}
/**
 * Comment creation, edit window enforcement, mention extraction and soft delete.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
 */
import { emit } from "@/lib/event-bus";
import { resolveMentions } from "@/lib/mentions";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import {
  actorEnvelope,
  commentResource,
  issueResource,
  requireFound,
} from "./_support";
import type {
  CreateCommentInput,
  DeleteCommentInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type { Comment, CommentThreadNode } from "@/types/comment";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** How long after posting an author may still edit their own comment. */
const EDIT_WINDOW_MS = 15 * 60 * 1000;

/** How many members are scanned when resolving `@handle` mentions. */
const MENTION_LOOKUP_LIMIT = 100;

/** Token bucket protecting the comment thread from burst posting. */
const COMMENT_CREATE_BUCKET = "comment:create";

/**
 * Posts a comment on a live issue. Mentions written as `@handle` in the body
 * are resolved against the org's members here, so the stored row and the
 * `comment.created` payload agree on who was mentioned — the notification
 * fan-out reads that list rather than re-parsing the markdown.
 */
export async function createComment(
  actor: Actor,
  input: CreateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "comment:create", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Comment rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const mentionedUserIds = await resolveMentionedUsers(
    input.orgId,
    input.body,
    input.mentionedUserIds,
  );

  const comment = await commentRepo.insertComment(
    { ...input, mentionedUserIds: [...mentionedUserIds] },
    actor.userId,
  );

  await emit("comment.created", {
    ...actorEnvelope(actor),
    commentId: comment.id,
    issueId: comment.issueId,
    mentionedUserIds,
  });

  return comment;
}

/**
 * Edits are allowed inside a fifteen-minute window, or by anyone the role
 * matrix already lets update a comment. `can()` decides the second half —
 * this service only owns the time window.
 */
export async function updateComment(
  actor: Actor,
  input: UpdateCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:update", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
    throw new Error("The edit window for this comment has closed");
  }

  return commentRepo.updateComment(input);
}

/**
 * Deletion is soft: the row keeps its place so replies below it still have an
 * anchor. `archivePatch()` is what the repository writes; asking for it here
 * documents that this service deliberately never issues a hard delete.
 */
export async function deleteComment(
  actor: Actor,
  input: DeleteCommentInput,
): Promise<Comment> {
  assertOrgScope(actor, input.orgId);

  const comment = requireFound(
    await commentRepo.findCommentById(input.orgId, input.commentId),
    "Comment",
    input.commentId,
  );
  assertCan(actor, "comment:delete", commentResource(comment));
  assertNotArchived("Comment", comment.id, comment);

  const { archivedAt } = archivePatch();
  const archived = await commentRepo.archiveComment(
    input.orgId,
    input.commentId,
  );

  await emit("comment.deleted", {
    ...actorEnvelope(actor),
    occurredAt: archivedAt,
    commentId: archived.id,
    issueId: archived.issueId,
  });

  return archived;
}

export async function getThread(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  return commentRepo.listThread(orgId, issueId);
}

function isPastEditWindow(comment: Comment): boolean {
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const known = new Set(members.items.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
